solution:
function CanJump(nums: int[]) -> bool {
  let reach = 0;
  let i = 0;
  let n = nums.length();
  while (i < n) {
    if (i > reach) {
      return false;
    }
    let far = i + nums[i];
    if (far > reach) {
      reach = far;
    }
    i += 1;
  }
  return true;
}
